import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

/**
 * D10-08. `lib/bff-schemas.ts` promises this test exists: every Nest path a BFF
 * route forwards to must be a real operation in the generated
 * `api/openapi.yaml`, so a renamed or deleted endpoint cannot drift silently.
 *
 * `api/openapi.yaml` is generated by the API repo and is stable; it is parsed
 * here as text because the web bundle has no YAML dependency and the only thing
 * needed is the set of top-level `paths:` keys.
 */

const here = dirname(fileURLToPath(import.meta.url));
const webRoot = join(here, "..");
const specPath = join(webRoot, "..", "api", "openapi.yaml");

function walk(dir: string): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === "node_modules" || entry.name === ".next") continue;
    const full = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walk(full));
    else if (/\.(ts|tsx)$/.test(entry.name)) out.push(full);
  }
  return out;
}

// Paths are 2-space-indented keys under `paths:` and all carry the `/api/v1`
// prefix; a path segment never contains a colon or whitespace.
const spec = readFileSync(specPath, "utf8");
const specPaths = new Set<string>();
for (const match of spec.matchAll(/^ {2}(\/api\/v1\/[^:\s]+):/gm)) {
  specPaths.add(match[1]);
}

interface Ref {
  file: string;
  path: string;
}

const routeFiles = walk(join(webRoot, "app", "api"));
const refs: Ref[] = [];
for (const file of routeFiles) {
  for (const line of readFileSync(file, "utf8").split(/\r?\n/)) {
    const trimmed = line.trim();
    if (trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*")) {
      continue;
    }
    const match = /path:\s*(["'`])([^"'`]+)\1/.exec(line);
    if (!match) continue;
    // `path: \`/admin/users/${id}/role\`` → `/admin/users/{id}/role`.
    const normalized = match[2].replace(/\$\{(\w+)\}/g, "{$1}");
    refs.push({ file: file.slice(webRoot.length + 1), path: `/api/v1${normalized}` });
  }
}

describe("D10-08 BFF upstream contract", () => {
  it("parses the OpenAPI operation paths", () => {
    assert.ok(specPaths.size > 0, "no /api/v1 paths parsed from api/openapi.yaml");
  });

  it("finds the BFF upstream references", () => {
    assert.ok(
      refs.length >= 60,
      `expected many proxy paths, found ${refs.length} (regex drift?)`,
    );
  });

  it("every BFF proxy path is a real operation in openapi.yaml", () => {
    const unclaimed = refs.filter((ref) => !specPaths.has(ref.path));
    const detail = unclaimed.map((ref) => `  ${ref.path}  ← ${ref.file}`).join("\n");
    assert.equal(
      unclaimed.length,
      0,
      `BFF paths with no matching OpenAPI operation:\n${detail}`,
    );
  });
});
